#: Refusal outcome (Section 3.7). NO_ANSWER: the data does not support an answer. UNRATIFIED: the value is proposed and not ratified. REFUSE: a rule forbids the action.
Refusal = Literal["NO_ANSWER", "UNRATIFIED", "REFUSE"]

Limit = int

Cursor = str

Fields = str

Sort = str

Filter = Dict[str, Dict[str, Any]]

IdempotencyKey = str

IfMatch = str

#: Jurisdiction identifier from `xpms.dim_jurisdiction`. An unpopulated jurisdiction returns no answer.
JurisdictionId = Optional[str]

#: Cost region code from `xpms.dim_region`.
RegionCode = Optional[str]

#: Tier of experience code from `xpms.dim_tier`.
TierCode = str

#: Phase code from `xpms.dim_phase`, ordered by gate ordinal.
PhaseCode = str

#: Gate criterion identifier from `xpms.dim_gate_criterion`.
CriterionId = str

#: Record kind from `xpms.dim_record_kind` (26 kinds, Section 3.10).
RecordKind = str

#: Kind-scoped record subtype from `xpms.dim_record_subtype`. A subtype of one kind cannot be stored on another.
RecordSubtype = Optional[str]

#: Record class from `xpms.dim_record_kind`, derived from the kind.
RecordClass = str

#: Record state (Section 3.10). Blocked names its blocker, Deferred carries a replan reason, Canceled is retained.
RecordState = Literal["Proposed", "Ready", "Scheduled", "Active", "Blocked", "In Review", "Complete", "Deferred", "Canceled"]

#: URID at discipline grain (`DDDD.DD`) or category grain (`DDDD.DD.DD`), as GL dimension 2 allows.
UridAtAnyGrain = Optional[str]

#: XYZ schema-family tag (Section 3.6): X Resource, Y Process, Z Timeline.
Xyz = str

#: External role type (Section 4.4.2).
ExternalRoleType = Literal["Client", "Vendor", "Contractor", "Crew", "Staff", "Artist", "Artist Representative", "Sponsor"]

#: Department class code from `xpms.dim_department` (Section 3.2).
DeptCode = Optional[str]

#: Require (a requirement) or provide (a capability).
Direction = Literal["require", "provide"]

#: Unit basis from the controlled unit list in `xpms.dim_unit_alias`.
UnitCode = Optional[str]

#: Requirement against capability result. Unknown against a critical requirement is a gap at gate 3.
ReconciliationResult = Literal["Met", "Gap", "Unknown"]

#: Hospitality fulfillment kind.
FulfillmentKind = Literal["Lodging", "Catering", "Travel", "Amenity"]

#: Catalog item identifier `{URID}-{ORG}-{SEQ}` (Section 3.6).
ItemId = Optional[str]

#: Category URID `DDDD.DD.DD` from `xpms.dim_category` (Section 3.3). There is no fourth segment.
Urid = str

#: Workforce role code from `xpms.dim_role`, on URID grammar.
RoleCode = str

#: Compensation rate type.
RateType = Literal["Hourly", "Day", "Flat", "Milestone", "Bid"]

#: Sustainability or compliance tag from `xpms.dim_tag`.
TagId = Optional[str]

#: GL account code from the fixed chart in `xpms.dim_gl_account` (Section 3.11).
